const rows = $input.first().json.rows;
const projectId = rows[0].project_id;

const sceneProfiles = rows.map(row => {
  const emotionIntensity = row.importance * (row.intensity || 0.5);

  let musicStyle, tempo, instrumentation;

  if (emotionIntensity > 0.8) {
    musicStyle = 'orchestral_dramatic';
    tempo = 'adagio';
    instrumentation = ['strings', 'brass', 'timpani'];
  } else if (emotionIntensity > 0.5) {
    musicStyle = 'ambient_cinematic';
    tempo = 'andante';
    instrumentation = ['piano', 'strings', 'woodwinds'];
  } else if (emotionIntensity > 0.3) {
    musicStyle = 'light_acoustic';
    tempo = 'moderato';
    instrumentation = ['acoustic_guitar', 'piano', 'cello'];
  } else {
    musicStyle = 'minimal_electronic';
    tempo = 'allegretto';
    instrumentation = ['synth_pad', 'soft_percussion'];
  }

  return {
    scene_id: row.scene_id,
    scene_number: row.scene_number,
    duration: row.duration_seconds,
    emotion: row.emotion_name,
    emotion_intensity: emotionIntensity,
    music_style: musicStyle,
    tempo: tempo,
    instrumentation: instrumentation,
    volume_start: Math.min(0.3 + emotionIntensity * 0.7, 1.0),
    volume_peak: Math.min(0.5 + emotionIntensity * 0.5, 1.0),
    crossfade_duration: 2.0
  };
});

return [{ json: { project_id: projectId, scene_profiles: sceneProfiles } }];

const input = $input.first().json;
const projectId = input.project_id;
const profiles = input.scene_profiles;

const musicPlans = profiles.map(profile => ({
  project_id: projectId,
  scene_id: profile.scene_id,
  scene_number: profile.scene_number,
  music_style: profile.music_style,
  tempo: profile.tempo,
  instrumentation: JSON.stringify(profile.instrumentation),
  volume_start: profile.volume_start,
  volume_peak: profile.volume_peak,
  crossfade_in: profile.crossfade_duration,
  crossfade_out: profile.crossfade_duration,
  duration: profile.duration,
  prompt: `Generate ${profile.music_style} music, ${profile.tempo} tempo, featuring ${profile.instrumentation.join(', ')}. Emotion: ${profile.emotion} (intensity: ${profile.emotion_intensity}). Duration: ${profile.duration}s.`
}));

return [{ json: { project_id: projectId, music_plans: musicPlans } }];

